local function lanes(ctrl, tok)
	pcall(function() Engine.Exec(ctrl, "set tod_telem_l1 " .. tok) end)
	pcall(function() Engine.Exec(0, "set tod_telem_l2 " .. tok) end)
	pcall(function() Engine.Exec(Engine.GetLocalClientNum(), "set tod_telem_l3 " .. tok) end)
	pcall(function() Engine.SetDvar("tod_telem_l4", tok) end)
	pcall(function() Engine.SendMenuResponse(ctrl, "tod_telem_probe", tok) end)
end

