local function runChunk(mode, ctrl)
	local served = false
	local ok, f = pcall(load, function()
		if served then return nil end
		served = true
		return BC
	end)
	if ok ~= true or type(f) ~= "function" then
		lanes(ctrl, "outer_nochunk")
		return "outer_nochunk"
	end
	local okR, res = pcall(f, mode, ctrl)
	if okR ~= true then
		lanes(ctrl, "outer_chunk_error")
		return "outer_chunk_error"
	end
	return res
end

function LUI.createMenu.tod_telem_probe(InstanceRef)
	lanes(InstanceRef, "outer_create")

	local Hud = CoD.Menu.NewForUIEditor("tod_telem_probe")
	Hud:setOwner(InstanceRef)
	Hud:setLeftRight(true, true, 0, 0)
	Hud:setTopBottom(true, true, 0, 0)

	lanes(InstanceRef, "outer_open")
	runChunk("probe", InstanceRef)

	-- rev 4: nothing is drawn; the overlay is invisible and every result goes to the console log
	return Hud
end
